const crypto = require('crypto');

// Example plaintext password
const plainTextPassword = "jdpassword";

// Create a hash of the password (using SHA256 as an example)
const hashedPassword = crypto.createHash('sha256').update(plainTextPassword).digest('hex');

// To verify, hash the input and compare with stored hash
function verifyPassword(input, hash) {
    const inputHash = crypto.createHash('sha256').update(input).digest('hex');
    return inputHash === hash;
}

// Example usage:
